def list_images(folder):
    """
    Return all image paths.
    """
    image_extensions = [".jpg", ".jpeg", ".png"]

    images = []

    for ext in image_extensions:
        images.extend(Path(folder).rglob(f"*{ext}"))

    return sorted(images)
